V;v\sim w}}x_{u}^{2}+\dfrac{1}{2}\sum_{\substack{u\in V;v\sim u}
}\sum_{\substack{w\in V;v\sim w}}x_{u}^{2}=\sum_{\substack{u\in V;v\sim
u}}\underbrace{\sum_{\substack{w\in V;v\sim w}}x_{u}^{2}}_{=\left(
\text{the number of }w\in V\text{ satisfying }v\sim w\right)  \cdot x_{u}^{2}
}
& =\sum_{\substack{u\in V;v\sim u}}\underbrace{\left(  \text{the number of
}w\in V\text{ satisfying }v\sim w\right)  }_{\substack{=\deg v\text{(by the
definition of }\deg v\text{,}\text{since }G\text{ is a simple graph)}}}\cdot
x_{u}^{2}
& =\sum_{\substack{u\in V;v\sim u}}\left(  \deg v\right)  \cdot x_{u}^{2}.
\end{align*}
Summing these inequalities over all  $v\in V$ , we find
\begin{align*}
\sum_{v\in V}y_{v}^{2}  & \leq\underbrace{\sum_{v\in V}\sum_{\substack{u\in
V;v\sim u}}}_{=\sum_{u\in V}\sum_{\substack{v\in V;v\sim u}}}\left(  \deg
v\right)  \cdot x_{u}^{2}=\sum_{u\in V}\sum_{\substack{v\in V;v\sim
u}}\left(  \deg v\right)  \cdot x_{u}^{2}
& =\sum_{v\in V}\underbrace{\sum_{\substack{w\in U;w\sim v}}}_{=\sum
_{\substack{w\in U;vw\in E}}}\left(  \deg w\right)  \cdot x_{v}
^{2}\ \ \ \ \ \ \ \ \ \ \left(
\begin{array}
[c]{c}
\text{here, we have renamed the}
\text{summation indices }u\text{ and }v\text{ as }v\text{ and }w
\end{array}
\right)  
& =\sum_{v\in V}\sum_{\substack{w\in U;vw\in E}}\left(  \deg w\right)  \cdot
x_{v}^{2}=\sum_{v\in V}\underbrace{\left(  \sum_{\substack{w\in U;vw\in
E}}\deg w\right)  }_{\substack{\leq n-1\text{(by the Claim you proved)}
}}\cdot x_{v}^{2}
& \leq\sum_{v\in V}\left(  n-1\right)  \cdot x_{v}^{2}=\left(  n-1\right)
\cdot\sum_{v\in V}x_{v}^{2}.
\end{align*}
Multiplying both sides of this inequality with the (clearly nonnegative) real  $\sum_{v\in V}x_{v}^{2}$ , we obtain
\[
\left(  \sum_{v\in V}x_{v}^{2}\right)  \left(  \sum_{v\in V}y_{v}^{2}\right)
\leq\left(  \sum_{v\in V}x_{v}^{2}\right)  \cdot\left(  n-1\right)  \cdot
\sum_{v\in V}x_{v}^{2}=\left(  n-1\right)  \cdot\left(  \sum_{v\in V}x_{v}
^{2}\right)  ^{2}.
\]
Hence,
\[
\left(  2\sum_{vw\in E}x_{v}x_{w}\right)  ^{2}\leq\left(  \sum_{v\in V}
x_{v}^{2}\right)  \left(  \sum_{v\in V}y_{v}^{2}\right)  \leq\left(
n-1\right)  \cdot\left(  \sum_{v\in V}x_{v}^{2}\right)  ^{2}.
\]
We can take square roots on both sides of this inequality (since both sides are obviously nonnegative), and thus find
\[
\left\vert 2\sum_{vw\in E}x_{v}x_{w}\right\vert \leq\sqrt{\left(  n-1\right)
\cdot\left(  \sum_{v\in V}x_{v}^{2}\right)  ^{2}}=\sqrt{n-1}\cdot\left\vert
\sum_{v\in V}x_{v}^{2}\right\vert =\sqrt{n-1}\cdot\sum_{v\in V}x_{v}^{2}
\]
(where we have dropped the absolute value sign because  $\sum_{v\in V}x_{v}^{2}\geq0$ ). Hence,
\[
\sqrt{n-1}\cdot\sum_{v\in V}x_{v}^{2}\geq\left\vert 2\sum_{vw\in E}x_{v}
x_{w}\right\vert \geq2\sum_{vw\in E}x_{v}x_{w}
\]
(since  $\left\vert u\right\vert \geq u$  for any real number  $u$ ). This completes the proof.  $\blacksquare$

