dot(" $A$ ",A,dir(O--A));
dot(" $B$ ",B,dir(O--B));
dot(" $C$ ",C,dir(O--C));
dot(" $I_c$ ",Ic,NW);
dot(" $I_b$ ",Ib,NE);
dot(" $N$ ",((Ib+Ic)/2),dir(90));
dot(" $O_c$ ",Oc,dir(Ob--Oc));
